/**
 * Declarative Drizzle schema for the Sigiro auth service on Cloudflare D1 (SQLite).
 *
 * THIS IS A REVIEWED ARTIFACT, NOT A BUILD OUTPUT.
 * ================================================
 * It is the single reviewable source of truth for the auth database's final
 * state. There are no migration deltas to replay in your head: what you read
 * here is what the database is.
 *
 * Generated from : better-auth 1.7.5 / @better-auth/drizzle-adapter 1.7.5
 * Generated by   : auth/scripts/generate-d1-schema.ts, which calls
 *                    generateDrizzleSchema({
 *                      options: createAuthOptions(...),  // the real auth/src/auth.ts config
 *                      provider: "sqlite",
 *                      camelCase: true,
 *                    })
 *                  from @better-auth/drizzle-adapter's internal
 *                  dist/generate-drizzle-schema-<contenthash>.mjs.
 *
 * REGENERATION IS MANUAL. The generator lives behind a content-hashed internal
 * filename that changes on every Better Auth release, so it is deliberately not
 * wired into CI. On a Better Auth upgrade, or when a plugin is added/removed in
 * auth/src/auth.ts, re-run the script, re-apply the two edits below, and review
 * the diff:
 *
 *   1. STRIP the trailing `authRelations` block and drop `defineRelationsPart`
 *      from the drizzle-orm import. `defineRelationsPart` does not exist in
 *      drizzle-orm 0.45.2 (verified: `typeof === "undefined"`), which is the
 *      lower half of Better Auth's own peer range
 *      `^0.45.2 || >=1.0.0-rc.1 <2.0.0`. The Drizzle adapter does not need
 *      relations; it resolves references from the table definitions.
 *   2. REGROUP the tables under the plugin that contributes them (below), so the
 *      file stays reviewable by origin rather than by generator emission order.
 *
 * Column definitions themselves are verbatim generator output — do not hand-tune
 * them. If a column looks wrong, fix the plugin config and regenerate.
 *
 * TRAP: `{ mode: "json" }` IS NOT INTERCHANGEABLE WITH PLAIN `text()`
 * ------------------------------------------------------------------
 * Four columns are declared by their plugins as PLAIN STRINGS with app-side
 * `transform.input` / `transform.output` doing the JSON encoding:
 *
 *   - agentHost.defaultCapabilities
 *   - agent.metadata
 *   - agentCapabilityGrant.constraints
 *   - organization.metadata
 *
 * Marking any of these `{ mode: "json" }` makes Drizzle serialize a value the
 * plugin has ALREADY serialized. The double-encoded string round-trips as a
 * JSON string instead of an object, and capability grants fail silently — no
 * error, just an agent that is quietly denied every capability. They MUST stay
 * plain `text()`. Other columns that genuinely are `{ mode: "json" }` (the
 * oauth* scope/resource arrays) are correct as generated.
 *
 * test/schema.ts pins all four columns, and the startup schema check in
 * src/schema/check.ts turns a missing table or column into a boot-time error.
 *
 * Table count: 21. emailOTP and cimd contribute zero tables.
 */

import { sql } from "drizzle-orm";
import {
  sqliteTable,
  text,
  integer,
  index,
  uniqueIndex,
} from "drizzle-orm/sqlite-core";

// --------------------------------------------------------------------------
// Core — better-auth core tables (betterAuth() itself)
// `session.activeOrganizationId` is contributed by the organization plugin;
// `verification` is reused verbatim by emailOTP({ storeOTP: 'hashed' }), which
// adds no table of its own.
// --------------------------------------------------------------------------

export const user = sqliteTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: integer("emailVerified", { mode: "boolean" })
    .default(false)
    .notNull(),
  image: text("image"),
  createdAt: integer("createdAt", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull(),
  updatedAt: integer("updatedAt", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .$onUpdate(() => /* @__PURE__ */ new Date())
    .notNull(),
});

export const session = sqliteTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: integer("expiresAt", { mode: "timestamp_ms" }).notNull(),
    token: text("token").notNull().unique(),
    createdAt: integer("createdAt", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updatedAt", { mode: "timestamp_ms" })
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
    ipAddress: text("ipAddress"),
    userAgent: text("userAgent"),
    userId: text("userId")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    activeOrganizationId: text("activeOrganizationId"),
  },
  (table) => [index("session_userId_idx").on(table.userId)]
);

